-- Samfélag is a member-visible feed, independent of invitation-only chat groups.
create table private.social_feed_communities(id uuid primary key default gen_random_uuid(),name text not null check(char_length(btrim(name)) between 1 and 80),description text not null default '' check(char_length(description)<=2000),status text not null default 'active' check(status in ('active','archived','hidden')),created_by uuid references public.profiles(id) on delete set null,created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp());
create table private.social_feed_memberships(community_id uuid references private.social_feed_communities(id) on delete cascade,profile_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default clock_timestamp(),primary key(community_id,profile_id));
create table private.social_feed_posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id) on delete cascade,community_id uuid references private.social_feed_communities(id) on delete cascade,request_id uuid not null,body text not null check(char_length(btrim(body)) between 1 and 2000),created_at timestamptz not null default clock_timestamp(),hidden_at timestamptz,deleted_at timestamptz,unique(author_id,request_id));
create index social_feed_posts_order on private.social_feed_posts(created_at desc,id desc) where hidden_at is null and deleted_at is null;
create index social_feed_posts_community on private.social_feed_posts(community_id,created_at desc,id desc);
create table private.social_feed_likes(post_id uuid references private.social_feed_posts(id) on delete cascade,profile_id uuid references public.profiles(id) on delete cascade,created_at timestamptz not null default clock_timestamp(),primary key(post_id,profile_id));
create table private.social_feed_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references private.social_feed_posts(id) on delete cascade,author_id uuid not null references public.profiles(id) on delete cascade,request_id uuid not null,body text not null check(char_length(btrim(body)) between 1 and 2000),created_at timestamptz not null default clock_timestamp(),hidden_at timestamptz,deleted_at timestamptz,unique(author_id,request_id));
create index social_feed_comments_order on private.social_feed_comments(post_id,created_at desc,id desc) where hidden_at is null and deleted_at is null;
create table private.social_feed_media(target_type text not null check(target_type in ('social_feed_post','community_cover')),target_id uuid not null,upload_id uuid not null unique references private.media_uploads(id) on delete cascade,owner_id uuid not null references public.profiles(id) on delete cascade,storage_path text not null unique,primary key(target_type,target_id));
do $$ declare item text; begin foreach item in array array['social_feed_communities','social_feed_memberships','social_feed_posts','social_feed_likes','social_feed_comments','social_feed_media'] loop execute format('alter table private.%I enable row level security',item); execute format('revoke all on private.%I from public,anon,authenticated,service_role',item); end loop; end $$;
create function private.social_feed_actor() returns uuid language plpgsql stable security definer set search_path='' as $$ declare caller uuid:=(select auth.uid()); begin if not private.account_is_active() or not private.current_user_is_ready(false) or not private.memory_actor_active(caller) then raise exception using errcode='42501',message='active_account_required'; end if; return caller; end $$;
create function private.social_feed_author_visible(p_author uuid,p_viewer uuid) returns boolean language sql stable security definer set search_path='' as $$ select private.memory_actor_active(p_author) and not private.meetup_block_exists(p_author,p_viewer) and exists(select 1 from public.profiles where id=p_author and (is_profile_visible or id=p_viewer)); $$;
create function private.social_feed_visible(p_post uuid,p_viewer uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from private.social_feed_posts p left join private.social_feed_communities c on c.id=p.community_id where p.id=p_post and p.deleted_at is null and p.hidden_at is null and (p.community_id is null or c.status<>'hidden') and private.social_feed_author_visible(p.author_id,p_viewer)); $$;
create function private.social_feed_author(p_author uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('id',p.id,'displayName',p.display_name,'pronouns',p.pronouns,'photoPath',(select photo.storage_path from public.profile_photos photo where photo.profile_id=p.id and photo.approval_status='approved' order by (photo.id=p.cover_photo_id) desc,photo.position,photo.id limit 1)) from public.profiles p where p.id=p_author; $$;
create function private.social_feed_community_payload(p_id uuid,p_viewer uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('id',c.id,'name',c.name,'description',c.description,'status',c.status,'createdAt',c.created_at,'memberCount',(select count(*) from private.social_feed_memberships m where m.community_id=c.id and private.memory_actor_active(m.profile_id)),'joined',exists(select 1 from private.social_feed_memberships m where m.community_id=c.id and m.profile_id=p_viewer),'coverPath',(select m.storage_path from private.social_feed_media m join private.media_uploads u on u.id=m.upload_id and u.status='approved' where m.target_type='community_cover' and m.target_id=c.id)) from private.social_feed_communities c where c.id=p_id; $$;
create function private.social_feed_post_payload(p_id uuid,p_viewer uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare item private.social_feed_posts; image_path text; image_state text; begin select * into item from private.social_feed_posts where id=p_id;
 select m.storage_path into image_path from private.social_feed_media m join private.media_uploads u on u.id=m.upload_id and u.status='approved' where m.target_type='social_feed_post' and m.target_id=p_id; image_state:=case when image_path is not null then 'approved' else 'none' end;
 if item.author_id=p_viewer and image_path is null then select case when u.status in ('reserved','processing','appealed') then 'pending' when u.status='rejected' then 'rejected' else 'none' end into image_state from private.media_uploads u where u.target_type='social_feed_post' and u.target_id=p_id and u.rejection_reason is distinct from 'upload_cancelled' order by u.created_at desc,u.id desc limit 1; end if;
 return jsonb_build_object('id',item.id,'author',private.social_feed_author(item.author_id),'community',(select jsonb_build_object('id',c.id,'name',c.name) from private.social_feed_communities c where c.id=item.community_id),'body',item.body,'createdAt',item.created_at,'liked',exists(select 1 from private.social_feed_likes where post_id=item.id and profile_id=p_viewer),'likeCount',(select count(*) from private.social_feed_likes where post_id=item.id and private.social_feed_author_visible(profile_id,p_viewer)),'commentCount',(select count(*) from private.social_feed_comments where post_id=item.id and deleted_at is null and hidden_at is null and private.social_feed_author_visible(author_id,p_viewer)),'canDelete',item.author_id=p_viewer,'imageStatus',coalesce(image_state,'none'),'imagePath',image_path); end $$;
create function private.social_feed_comment_payload(p_id uuid,p_viewer uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('id',c.id,'postId',c.post_id,'author',private.social_feed_author(c.author_id),'body',c.body,'createdAt',c.created_at,'canDelete',c.author_id=p_viewer) from private.social_feed_comments c where c.id=p_id; $$;
create function private.social_feed_directory_impl() returns jsonb language plpgsql stable security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); begin return coalesce((select jsonb_agg(private.social_feed_community_payload(c.id,caller) order by lower(c.name),c.id) from private.social_feed_communities c where c.status='active'),'[]'); end $$;
create function private.social_feed_community_impl(p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); begin if not exists(select 1 from private.social_feed_communities where id=p_id and status<>'hidden') then raise exception using errcode='42501',message='social_feed_unavailable'; end if; return private.social_feed_community_payload(p_id,caller); end $$;
create function private.social_feed_membership_impl(p_id uuid,p_joined boolean) returns jsonb language plpgsql security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); item private.social_feed_communities; begin select * into item from private.social_feed_communities where id=p_id for update; if item.id is null or item.status='hidden' or p_joined is null then raise exception using errcode='42501',message='social_feed_unavailable'; end if;
 if p_joined then if item.status<>'active' then raise exception using errcode='23514',message='community_archived'; end if; insert into private.social_feed_memberships(community_id,profile_id) values(p_id,caller) on conflict do nothing; else delete from private.social_feed_memberships where community_id=p_id and profile_id=caller; end if; return private.social_feed_community_payload(p_id,caller); end $$;
create function private.social_feed_posts_impl(p_community uuid,p_cursor text,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); cursor_time timestamptz; cursor_id uuid; rows jsonb; more boolean; last_row jsonb; begin
 if p_limit is null or p_limit not between 1 and 50 then raise exception using errcode='22023',message='invalid_page_size'; end if; if p_community is not null then perform private.social_feed_community_impl(p_community); end if;
 if p_cursor is not null then begin cursor_time:=(p_cursor::jsonb->>'createdAt')::timestamptz; cursor_id:=(p_cursor::jsonb->>'id')::uuid; if cursor_time is null or cursor_id is null then raise exception 'invalid'; end if; exception when others then raise exception using errcode='22023',message='invalid_cursor'; end; end if;
 select coalesce(jsonb_agg(private.social_feed_post_payload(p.id,caller) order by p.created_at desc,p.id desc),'[]'),count(*)>p_limit into rows,more from (select * from private.social_feed_posts p where (p_community is null or p.community_id=p_community) and private.social_feed_visible(p.id,caller) and (cursor_time is null or (p.created_at,p.id)<(cursor_time,cursor_id)) order by p.created_at desc,p.id desc limit p_limit+1) p;
 if more then rows:=rows-(jsonb_array_length(rows)-1); end if; last_row:=rows->(jsonb_array_length(rows)-1); return jsonb_build_object('items',rows,'nextCursor',case when more then jsonb_build_object('createdAt',last_row->>'createdAt','id',last_row->>'id')::text end); end $$;
create function private.social_feed_post_impl(p_id uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); begin if not private.social_feed_visible(p_id,caller) then raise exception using errcode='42501',message='social_feed_unavailable'; end if; return private.social_feed_post_payload(p_id,caller); end $$;
create function private.social_feed_publish_impl(p_request uuid,p_community uuid,p_body text) returns jsonb language plpgsql security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); existing private.social_feed_posts; result uuid; begin if p_request is null or p_body is null or char_length(btrim(p_body)) not between 1 and 2000 then raise exception using errcode='22023',message='invalid_social_feed_body'; end if;
 perform pg_advisory_xact_lock(hashtextextended(caller::text||p_request::text,0)); select * into existing from private.social_feed_posts where author_id=caller and request_id=p_request;
 if existing.id is not null then if existing.body<>btrim(p_body) or existing.community_id is distinct from p_community then raise exception using errcode='23505',message='social_feed_request_conflict'; end if; return private.social_feed_post_impl(existing.id); end if;
 if p_community is not null then perform 1 from private.social_feed_communities where id=p_community for share; if not exists(select 1 from private.social_feed_communities c join private.social_feed_memberships m on m.community_id=c.id and m.profile_id=caller where c.id=p_community and c.status='active') then raise exception using errcode='42501',message='community_membership_required'; end if; end if;
 perform private.consume_write_quota('social_feed_publish',20,interval '1 hour'); insert into private.social_feed_posts(author_id,community_id,request_id,body) values(caller,p_community,p_request,btrim(p_body)) returning id into result; return private.social_feed_post_payload(result,caller); end $$;
create function private.social_feed_like_impl(p_id uuid,p_liked boolean) returns jsonb language plpgsql security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); begin perform 1 from private.social_feed_posts where id=p_id for share; if p_liked is null or not private.social_feed_visible(p_id,caller) then raise exception using errcode='42501',message='social_feed_unavailable'; end if; if p_liked then insert into private.social_feed_likes(post_id,profile_id) values(p_id,caller) on conflict do nothing; else delete from private.social_feed_likes where post_id=p_id and profile_id=caller; end if; return private.social_feed_post_payload(p_id,caller); end $$;
create function private.social_feed_comments_impl(p_post uuid,p_cursor text,p_limit integer) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); cursor_time timestamptz; cursor_id uuid; rows jsonb; more boolean; last_row jsonb; begin if p_limit is null or p_limit not between 1 and 50 then raise exception using errcode='22023',message='invalid_page_size'; end if; if not private.social_feed_visible(p_post,caller) then raise exception using errcode='42501',message='social_feed_unavailable'; end if;
 if p_cursor is not null then begin cursor_time:=(p_cursor::jsonb->>'createdAt')::timestamptz; cursor_id:=(p_cursor::jsonb->>'id')::uuid; if cursor_time is null or cursor_id is null then raise exception 'invalid'; end if; exception when others then raise exception using errcode='22023',message='invalid_cursor'; end; end if;
 select coalesce(jsonb_agg(private.social_feed_comment_payload(c.id,caller) order by c.created_at desc,c.id desc),'[]'),count(*)>p_limit into rows,more from (select * from private.social_feed_comments c where c.post_id=p_post and c.hidden_at is null and c.deleted_at is null and private.social_feed_author_visible(c.author_id,caller) and (cursor_time is null or (c.created_at,c.id)<(cursor_time,cursor_id)) order by c.created_at desc,c.id desc limit p_limit+1) c;
 if more then rows:=rows-(jsonb_array_length(rows)-1); end if; last_row:=rows->(jsonb_array_length(rows)-1); return jsonb_build_object('items',rows,'nextCursor',case when more then jsonb_build_object('createdAt',last_row->>'createdAt','id',last_row->>'id')::text end); end $$;
create function private.social_feed_comment_impl(p_post uuid,p_request uuid,p_body text) returns jsonb language plpgsql security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); existing private.social_feed_comments; result uuid; begin if p_request is null or p_body is null or char_length(btrim(p_body)) not between 1 and 2000 then raise exception using errcode='22023',message='invalid_social_feed_body'; end if;
 perform pg_advisory_xact_lock(hashtextextended(caller::text||p_request::text,0)); perform 1 from private.social_feed_posts where id=p_post for share; if not private.social_feed_visible(p_post,caller) then raise exception using errcode='42501',message='social_feed_unavailable'; end if;
 select * into existing from private.social_feed_comments where author_id=caller and request_id=p_request; if existing.id is not null then if existing.body<>btrim(p_body) or existing.post_id<>p_post or existing.hidden_at is not null or existing.deleted_at is not null then raise exception using errcode='23505',message='social_feed_request_conflict'; end if; return private.social_feed_comment_payload(existing.id,caller); end if;
 perform private.consume_write_quota('social_feed_comment',60,interval '1 hour'); insert into private.social_feed_comments(post_id,author_id,request_id,body) values(p_post,caller,p_request,btrim(p_body)) returning id into result; return private.social_feed_comment_payload(result,caller); end $$;
create function private.social_feed_delete_impl(p_kind text,p_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); owner uuid; begin if p_kind='post' then select author_id into owner from private.social_feed_posts where id=p_id for update; elsif p_kind='comment' then select author_id into owner from private.social_feed_comments where id=p_id for update; else raise exception using errcode='22023',message='invalid_social_feed_target'; end if;
 if owner is null then return; end if; if owner<>caller then raise exception using errcode='42501',message='social_feed_owner_required'; end if;
 if p_kind='post' then update private.social_feed_posts set deleted_at=coalesce(deleted_at,clock_timestamp()) where id=p_id; update private.media_uploads set status='rejected',rejection_reason='social_feed_deleted',claim_id=null where target_type='social_feed_post' and target_id=p_id; delete from private.social_feed_media where target_type='social_feed_post' and target_id=p_id; else update private.social_feed_comments set deleted_at=coalesce(deleted_at,clock_timestamp()) where id=p_id; end if; end $$;
alter table public.reports add column social_feed_post_id uuid references private.social_feed_posts(id) on delete set null deferrable initially deferred,add column social_feed_comment_id uuid references private.social_feed_comments(id) on delete set null deferrable initially deferred,add column social_feed_snapshot jsonb,add column social_feed_request_id uuid;
create unique index social_feed_report_request on public.reports(reporter_id,social_feed_request_id) where social_feed_request_id is not null;
create function private.social_feed_report_impl(p_kind text,p_id uuid,p_category text,p_details text,p_request uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare caller uuid:=private.social_feed_actor(); owner uuid; post_id uuid; snapshot jsonb; result uuid; existing public.reports; begin
 if p_request is null or p_kind is null or p_kind not in ('post','comment') or p_category is null or p_category not in ('minor_suspected','csam','threat','ncii','harassment','coercion_non_consent','dangerous_location','misrepresentation','hate_discrimination','spam_advertising','trafficking_exploitation','illegal_activity','compensated_sexual_services','other') or p_details is null or char_length(p_details)>2000 then raise exception using errcode='22023',message='invalid_social_feed_report'; end if;
 perform pg_advisory_xact_lock(hashtextextended(caller::text||p_request::text,0)); select * into existing from public.reports where reporter_id=caller and social_feed_request_id=p_request; if existing.id is not null then if existing.category is distinct from p_category or existing.details is distinct from btrim(p_details) or existing.social_feed_snapshot->>'id' is distinct from p_id::text or existing.social_feed_snapshot->>'kind' is distinct from p_kind then raise exception using errcode='23505',message='social_feed_request_conflict'; end if; return existing.id; end if;
 if p_kind='post' then select p.author_id,p.id into owner,post_id from private.social_feed_posts p where p.id=p_id; snapshot:=private.social_feed_post_payload(p_id,caller); else select c.author_id,c.post_id into owner,post_id from private.social_feed_comments c where c.id=p_id and c.hidden_at is null and c.deleted_at is null and private.social_feed_author_visible(c.author_id,caller); snapshot:=private.social_feed_comment_payload(p_id,caller); end if;
 if owner is null or owner=caller or not private.social_feed_visible(post_id,caller) then raise exception using errcode='42501',message='social_feed_unavailable'; end if; perform private.consume_write_quota('social_feed_report',10,interval '1 hour');
 insert into public.reports(reporter_id,reported_id,category,details,social_feed_post_id,social_feed_comment_id,social_feed_snapshot,social_feed_request_id) values(caller,owner,p_category,btrim(p_details),post_id,case when p_kind='comment' then p_id end,snapshot||jsonb_build_object('kind',p_kind,'capturedAt',clock_timestamp()),p_request) returning id into result; return result; end $$;
create function private.social_feed_staff_directory_impl() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin perform private.require_staff(); return coalesce((select jsonb_agg(private.social_feed_community_payload(id,(select auth.uid())) order by lower(name),id) from private.social_feed_communities),'[]'); end $$;
create function private.social_feed_staff_save_impl(p_id uuid,p_name text,p_description text,p_status text,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$ begin perform private.require_staff(); if p_id is null or p_name is null or char_length(btrim(p_name)) not between 1 and 80 or p_description is null or char_length(p_description)>2000 or p_status is null or p_status not in ('active','archived','hidden') or p_reason is null or char_length(btrim(p_reason)) not between 8 and 1000 then raise exception using errcode='22023',message='invalid_community'; end if;
 insert into private.social_feed_communities(id,name,description,status,created_by) values(p_id,btrim(p_name),btrim(p_description),p_status,(select auth.uid())) on conflict(id) do update set name=excluded.name,description=excluded.description,status=excluded.status,updated_at=clock_timestamp(); insert into private.admin_audit_log(actor_id,action,target_type,target_id,details) values((select auth.uid()),'community_save','public_community',p_id::text,jsonb_build_object('reason',btrim(p_reason),'status',p_status)); return private.social_feed_community_payload(p_id,(select auth.uid())); end $$;
create function private.social_feed_staff_moderate_impl(p_kind text,p_id uuid,p_hidden boolean,p_reason text) returns void language plpgsql security definer set search_path='' as $$ declare changed integer; begin perform private.require_staff(); if p_hidden is null or p_reason is null or char_length(btrim(p_reason)) not between 8 and 1000 then raise exception using errcode='22023',message='invalid_moderation'; end if;
 if p_kind='post' then update private.social_feed_posts set hidden_at=case when p_hidden then clock_timestamp() end where id=p_id and deleted_at is null; elsif p_kind='comment' then update private.social_feed_comments set hidden_at=case when p_hidden then clock_timestamp() end where id=p_id and deleted_at is null; else raise exception using errcode='22023',message='invalid_social_feed_target'; end if;
 get diagnostics changed=row_count; if changed=0 then raise exception using errcode='P0002',message='social_feed_not_found'; end if; insert into private.admin_audit_log(actor_id,action,target_type,target_id,details) values((select auth.uid()),case when p_hidden then 'social_feed_hide' else 'social_feed_restore' end,'social_feed_'||p_kind,p_id::text,jsonb_build_object('reason',btrim(p_reason))); end $$;
create function private.social_feed_staff_reports_impl() returns jsonb language plpgsql stable security definer set search_path='' as $$ begin perform private.require_staff(); return coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc,r.id desc) from (select id,category,details,status,created_at,social_feed_post_id,social_feed_comment_id,social_feed_snapshot from public.reports where social_feed_snapshot is not null order by created_at desc,id desc limit 100) r),'[]'); end $$;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('social-feed-media','social-feed-media',false,10485760,array['image/jpeg']);
alter table private.media_uploads drop constraint media_uploads_target_type_check;
alter table private.media_uploads add constraint media_uploads_target_type_check check(target_type in ('album','profile_photo','profile_video','message','meetup','meetup_memory','showcase','strax','meetup_room_message','meetup_room_avatar','social_feed_post','community_cover'));
alter table private.media_cleanup_jobs drop constraint media_cleanup_jobs_bucket_check;
alter table private.media_cleanup_jobs add constraint media_cleanup_jobs_bucket_check check(bucket in ('media-quarantine','meetup-media','showcase-media','profile-photos','strax-media','meetup-room-media','social-feed-media'));
alter function private.media_target_available(uuid,text,uuid,uuid) rename to media_target_available_before_social_feed;
create function private.media_target_available(p_owner uuid,p_type text,p_target uuid,p_album uuid) returns boolean language sql stable security definer set search_path='' as $$ select case when p_type='social_feed_post' then private.memory_actor_active(p_owner) and exists(select 1 from private.social_feed_posts p left join private.social_feed_communities c on c.id=p.community_id where p.id=p_target and p.author_id=p_owner and p.hidden_at is null and p.deleted_at is null and (p.community_id is null or c.status='active'))
 when p_type='community_cover' then exists(select 1 from private.social_feed_communities where id=p_target and status<>'hidden') and exists(select 1 from auth.users u join public.profiles p on p.id=u.id where u.id=p_owner and p.moderation_status='active' and p.deletion_requested_at is null and not exists(select 1 from private.media_restore_quarantine where account_id=p.id)
 and (u.raw_app_meta_data->>'role' in ('moderator','admin','super_admin') or jsonb_typeof(u.raw_app_meta_data->'roles')='array' and u.raw_app_meta_data->'roles' ?| array['moderator','admin','super_admin']))
 else private.media_target_available_before_social_feed(p_owner,p_type,p_target,p_album) end; $$;
alter function private.reserve_media_upload_impl(text,uuid,text,jsonb) rename to reserve_media_before_social_feed;
create function private.reserve_media_upload_impl(p_type text,p_target uuid,p_kind text,p_metadata jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare caller uuid; item private.media_uploads; upload_id uuid:=gen_random_uuid(); request uuid; begin
 if p_type not in ('social_feed_post','community_cover') then return private.reserve_media_before_social_feed(p_type,p_target,p_kind,p_metadata); end if;
 if p_type='community_cover' then perform private.require_staff(); caller:=(select auth.uid()); perform 1 from private.social_feed_communities where id=p_target for update; else caller:=private.social_feed_actor(); perform 1 from private.social_feed_posts where id=p_target for update; end if;
 if p_kind is distinct from 'image' or p_metadata is null or jsonb_typeof(p_metadata)<>'object' or p_metadata-array['tags','requestId']<>'{}'::jsonb or coalesce(p_metadata->'tags','[]')<>'[]'::jsonb or p_type='social_feed_post' and p_metadata ? 'requestId' then raise exception using errcode='22023',message='invalid_media_metadata'; end if;
 if p_type='community_cover' then request:=(p_metadata->>'requestId')::uuid; if request is null then raise exception using errcode='22023',message='invalid_media_metadata'; end if; end if;
 if not private.media_target_available(caller,p_type,p_target,null) then raise exception using errcode='42501',message='media_target_unavailable'; end if;
 select * into item from private.media_uploads where owner_id=caller and target_type=p_type and target_id=p_target and status in ('reserved','processing','approved','appealed') and (p_type='social_feed_post' or metadata->>'requestId'=request::text) order by created_at desc,id desc limit 1;
 if item.id is not null and (item.status<>'reserved' or item.expires_at>now()) then return jsonb_build_object('id',item.id,'bucket','media-quarantine','path',item.object_path,'alreadyUploaded',item.status<>'reserved' or exists(select 1 from storage.objects where bucket_id='media-quarantine' and name=item.object_path)); end if;
 perform private.consume_write_quota('social_feed_media',20,interval '1 hour'); update private.media_uploads set status='rejected',rejection_reason='upload_cancelled',claim_id=null where target_type=p_type and target_id=p_target and status in ('reserved','processing','appealed') and (p_type='community_cover' or expires_at<=now());
 insert into private.media_uploads(id,owner_id,target_type,target_id,media_type,object_path,metadata) values(upload_id,caller,p_type,p_target,'image',caller::text||'/'||upload_id::text,case when request is null then '{}'::jsonb else jsonb_build_object('requestId',request) end); return jsonb_build_object('id',upload_id,'bucket','media-quarantine','path',caller::text||'/'||upload_id::text,'alreadyUploaded',false); end $$;
create or replace function public.reserve_media_upload(target_type text,target_id uuid,media_type text,metadata jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$ select private.reserve_media_upload_impl(target_type,target_id,media_type,metadata); $$;
alter function private.finish_media_impl(uuid,uuid,integer,integer,text,text,text) rename to finish_media_before_social_feed;
create function private.finish_media_impl(p_id uuid,p_claim uuid,p_bytes integer,p_duration integer,p_path text,p_thumbnail text,p_reason text) returns boolean language plpgsql security definer set search_path='' as $$ declare item private.media_uploads; begin perform private.require_service_role(); select * into item from private.media_uploads where id=p_id;
 if item.id is null or item.target_type not in ('social_feed_post','community_cover') then return private.finish_media_before_social_feed(p_id,p_claim,p_bytes,p_duration,p_path,p_thumbnail,p_reason); end if;
 if item.target_type='social_feed_post' then perform 1 from private.social_feed_posts where id=item.target_id for update; else perform 1 from private.social_feed_communities where id=item.target_id for update; end if; select * into item from private.media_uploads where id=p_id for update;
 if p_claim is null or item.claim_id is distinct from p_claim or item.status<>'processing' or item.expires_at<=now() then return false; end if;
 if not private.media_target_available(item.owner_id,item.target_type,item.target_id,null) then p_reason:='media_target_unavailable'; end if;
 if p_reason is not null then update private.media_uploads set status='rejected',rejection_reason=p_reason,claim_id=null where id=p_id; return true; end if;
 if p_path is distinct from item.target_id::text||'/'||item.id::text||'.jpg' or p_bytes is null or p_bytes not between 1 and 10485760 or p_duration is not null or p_thumbnail is not null then raise exception using errcode='22023',message='invalid_verified_media'; end if;
 update private.media_uploads set status='approved',verified_bytes=p_bytes,normalized_path=p_path,verified_duration_ms=null,claim_id=null where id=p_id;
 insert into private.social_feed_media(target_type,target_id,upload_id,owner_id,storage_path) values(item.target_type,item.target_id,item.id,item.owner_id,p_path) on conflict(target_type,target_id) do update set upload_id=excluded.upload_id,owner_id=excluded.owner_id,storage_path=excluded.storage_path;
 insert into private.media_cleanup_jobs(bucket,name) values('media-quarantine',item.object_path) on conflict do nothing; return true; end $$;
create or replace function public.finish_media_upload(job_id uuid,claim_id uuid,byte_size integer,duration_ms integer,object_path text,thumbnail_path text,rejection_reason text) returns boolean language sql security invoker set search_path='' as $$ select private.finish_media_impl(job_id,claim_id,byte_size,duration_ms,object_path,thumbnail_path,rejection_reason); $$;
create function private.social_feed_media_read(p_name text) returns boolean language plpgsql stable security definer set search_path='' as $$ declare caller uuid; begin if private.is_admin() then return exists(select 1 from private.social_feed_media m join private.media_uploads u on u.id=m.upload_id and u.status='approved' where m.storage_path=p_name); end if; if not private.account_is_active() or not private.current_user_is_ready(false) or not private.memory_actor_active((select auth.uid())) then return false; end if; caller:=(select auth.uid()); return exists(select 1 from private.social_feed_media m join private.media_uploads u on u.id=m.upload_id and u.status='approved' where m.storage_path=p_name and (m.target_type='social_feed_post' and private.social_feed_visible(m.target_id,caller) or m.target_type='community_cover' and exists(select 1 from private.social_feed_communities where id=m.target_id and status<>'hidden'))); end $$;
create policy social_feed_media_read on storage.objects for select to authenticated using(bucket_id='social-feed-media' and private.social_feed_media_read(name));
create policy social_feed_media_visibility on storage.objects as restrictive for select to authenticated using(bucket_id<>'social-feed-media' or private.social_feed_media_read(name));
create function private.social_feed_author_photo_read(p_name text) returns boolean language sql stable security definer set search_path='' as $$
 select private.account_is_active() and private.current_user_is_ready(false) and exists(select 1 from public.profile_photos photo where photo.storage_path=p_name and photo.approval_status='approved'
 and private.social_feed_author_visible(photo.profile_id,(select auth.uid())) and (exists(select 1 from private.social_feed_posts p where p.author_id=photo.profile_id and private.social_feed_visible(p.id,(select auth.uid())))
 or exists(select 1 from private.social_feed_comments c where c.author_id=photo.profile_id and c.hidden_at is null and c.deleted_at is null and private.social_feed_visible(c.post_id,(select auth.uid())))));
$$;
create policy social_feed_author_photo_read on storage.objects for select to authenticated using(bucket_id='profile-photos' and private.social_feed_author_photo_read(name));
create function private.social_feed_media_cleanup() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into private.media_cleanup_jobs(bucket,name) values('social-feed-media',old.storage_path) on conflict do nothing; return old; end $$;
create trigger social_feed_media_cleanup after delete on private.social_feed_media for each row execute function private.social_feed_media_cleanup();
create trigger social_feed_replaced_media_cleanup after update of storage_path on private.social_feed_media for each row when(old.storage_path is distinct from new.storage_path) execute function private.social_feed_media_cleanup();
create function private.social_feed_upload_cleanup() returns trigger language plpgsql security definer set search_path='' as $$ declare item private.media_uploads; available timestamptz; begin item:=case when tg_op='DELETE' then old else new end; if item.target_type not in ('social_feed_post','community_cover') then return item; end if;
 if tg_op='DELETE' or item.status='rejected' then available:=greatest(clock_timestamp(),case when old.status='processing' then old.expires_at else clock_timestamp() end); insert into private.media_cleanup_jobs(bucket,name,available_at) values('social-feed-media',item.target_id::text||'/'||item.id::text||'.jpg',available) on conflict do nothing;
 if tg_op='DELETE' or item.rejection_reason in ('upload_cancelled','media_target_unavailable','social_feed_deleted') then insert into private.media_cleanup_jobs(bucket,name,available_at) values('media-quarantine',item.object_path,available) on conflict do nothing; end if; end if; return item; end $$;
create trigger social_feed_upload_cleanup after update of status or delete on private.media_uploads for each row execute function private.social_feed_upload_cleanup();
alter function private.account_owns_stored_object(uuid,text,text,text) rename to account_owns_stored_object_before_social_feed;
create function private.account_owns_stored_object(p_account uuid,p_bucket text,p_name text,p_owner text) returns boolean language sql stable security definer set search_path='' as $$ select private.account_owns_stored_object_before_social_feed(p_account,p_bucket,p_name,p_owner) or p_bucket='social-feed-media' and exists(select 1 from private.media_uploads u where u.owner_id=p_account and u.target_type in ('social_feed_post','community_cover') and p_name=u.target_id::text||'/'||u.id::text||'.jpg'); $$;
alter function private.owns_export_media(text,text,text) rename to owns_export_media_before_social_feed;
create function private.owns_export_media(p_bucket text,p_name text,p_owner text) returns boolean language sql stable security definer set search_path='' as $$ select private.owns_export_media_before_social_feed(p_bucket,p_name,p_owner) or p_bucket='social-feed-media' and exists(select 1 from private.social_feed_media where owner_id=(select auth.uid()) and storage_path=p_name); $$;
alter function private.export_account_impl() rename to export_account_before_social_feed;
create function private.export_account_impl() returns jsonb language plpgsql stable security definer set search_path='' as $$ declare caller uuid:=(select auth.uid()); begin if not private.account_is_active() then raise exception using errcode='42501',message='account_unavailable'; end if;
 return private.export_account_before_social_feed()||jsonb_build_object('communityMemberships',coalesce((select jsonb_agg(to_jsonb(m)) from private.social_feed_memberships m where profile_id=caller),'[]'),'communityPosts',coalesce((select jsonb_agg(to_jsonb(p)-'request_id') from private.social_feed_posts p where author_id=caller),'[]'),'communityComments',coalesce((select jsonb_agg(to_jsonb(c)-'request_id') from private.social_feed_comments c where author_id=caller),'[]'),'communityLikes',coalesce((select jsonb_agg(to_jsonb(l)) from private.social_feed_likes l where profile_id=caller),'[]'),'communityMedia',coalesce((select jsonb_agg(to_jsonb(m)) from private.social_feed_media m where owner_id=caller),'[]')); end $$;
alter view private.recoverable_media rename to recoverable_media_before_social_feed;
create view private.recoverable_media as select * from private.recoverable_media_before_social_feed union select 'social-feed-media'::text,m.storage_path,m.owner_id from private.social_feed_media m join private.media_uploads u on u.id=m.upload_id where u.status='approved' and private.memory_actor_active(m.owner_id);
revoke all on private.recoverable_media,private.recoverable_media_before_social_feed from public,anon,authenticated,service_role;

create function public.social_feed_directory() returns jsonb language sql stable security invoker set search_path='' as $$ select private.social_feed_directory_impl(); $$;
create function public.social_feed_community(p_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$ select private.social_feed_community_impl(p_id); $$;
create function public.social_feed_membership(p_id uuid,p_joined boolean) returns jsonb language sql security invoker set search_path='' as $$ select private.social_feed_membership_impl(p_id,p_joined); $$;
create function public.social_feed_posts(p_community uuid default null,p_cursor text default null,p_limit integer default 20) returns jsonb language sql stable security invoker set search_path='' as $$ select private.social_feed_posts_impl(p_community,p_cursor,p_limit); $$;
create function public.social_feed_post(p_id uuid) returns jsonb language sql stable security invoker set search_path='' as $$ select private.social_feed_post_impl(p_id); $$;
create function public.social_feed_publish(p_request uuid,p_community uuid,p_body text) returns jsonb language sql security invoker set search_path='' as $$ select private.social_feed_publish_impl(p_request,p_community,p_body); $$;
create function public.social_feed_like(p_id uuid,p_liked boolean) returns jsonb language sql security invoker set search_path='' as $$ select private.social_feed_like_impl(p_id,p_liked); $$;
create function public.social_feed_comments(p_post uuid,p_cursor text default null,p_limit integer default 20) returns jsonb language sql stable security invoker set search_path='' as $$ select private.social_feed_comments_impl(p_post,p_cursor,p_limit); $$;
create function public.social_feed_comment(p_post uuid,p_request uuid,p_body text) returns jsonb language sql security invoker set search_path='' as $$ select private.social_feed_comment_impl(p_post,p_request,p_body); $$;
create function public.social_feed_delete(p_kind text,p_id uuid) returns void language sql security invoker set search_path='' as $$ select private.social_feed_delete_impl(p_kind,p_id); $$;
create function public.social_feed_report(p_kind text,p_id uuid,p_category text,p_details text,p_request uuid) returns uuid language sql security invoker set search_path='' as $$ select private.social_feed_report_impl(p_kind,p_id,p_category,p_details,p_request); $$;
create function public.social_feed_staff_directory() returns jsonb language sql stable security invoker set search_path='' as $$ select private.social_feed_staff_directory_impl(); $$;
create function public.social_feed_staff_save(p_id uuid,p_name text,p_description text,p_status text,p_reason text) returns jsonb language sql security invoker set search_path='' as $$ select private.social_feed_staff_save_impl(p_id,p_name,p_description,p_status,p_reason); $$;
create function public.social_feed_staff_moderate(p_kind text,p_id uuid,p_hidden boolean,p_reason text) returns void language sql security invoker set search_path='' as $$ select private.social_feed_staff_moderate_impl(p_kind,p_id,p_hidden,p_reason); $$;
create function public.social_feed_staff_reports() returns jsonb language sql stable security invoker set search_path='' as $$ select private.social_feed_staff_reports_impl(); $$;
do $$ declare fn record; begin for fn in select p.oid::regprocedure signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and (p.proname like 'social_feed_%' or p.proname in ('media_target_available','media_target_available_before_social_feed','reserve_media_upload_impl','reserve_media_before_social_feed','finish_media_impl','finish_media_before_social_feed','account_owns_stored_object','account_owns_stored_object_before_social_feed','owns_export_media','owns_export_media_before_social_feed','export_account_impl','export_account_before_social_feed')) loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',fn.signature); if fn.nspname='public' or fn.proname like 'social_feed_%_impl' or fn.proname in ('social_feed_media_read','social_feed_author_photo_read','reserve_media_upload_impl','export_account_impl') then execute format('grant execute on function %s to authenticated',fn.signature); end if; if fn.proname='finish_media_impl' then execute format('grant execute on function %s to service_role',fn.signature); end if; end loop; end $$;
